-- Versioned legal releases; drafts cannot create acceptance records.
create table public.legal_releases (
 id uuid primary key default gen_random_uuid(),
 version text not null unique check(length(version) between 1 and 60),
 status text not null default 'draft' check(status in ('draft','published','retired')),
 operator jsonb not null default '{}'::jsonb,
 documents jsonb not null check(jsonb_typeof(documents)='array' and jsonb_array_length(documents)=6),
 content_sha256 text not null,
 created_at timestamptz not null default now(),
 published_at timestamptz,
 retired_at timestamptz
);
create unique index legal_one_published on public.legal_releases(status) where status='published';
create table public.legal_acceptances (
 id uuid primary key default gen_random_uuid(),
 release_id uuid not null references public.legal_releases(id),
 user_id uuid not null references auth.users(id) on delete restrict,
 audience text not null check(audience in ('client','worker')),
 source text not null check(source in ('signup','account','checkout')),
 terms_accepted boolean not null check(terms_accepted),
 privacy_acknowledged boolean not null check(privacy_acknowledged),
 worker_conditions_accepted boolean not null,
 content_sha256 text not null,
 accepted_at timestamptz not null default now(),
 unique(release_id,user_id,audience),
 check(audience<>'worker' or worker_conditions_accepted)
);
create index legal_acceptances_user_idx on public.legal_acceptances(user_id,accepted_at desc);
create table public.service_agreements (
 task_id uuid primary key references public.tasks(id),
 client_id uuid not null references public.profiles(id),
 worker_id uuid not null references public.profiles(id),
 offer_id uuid not null references public.task_offers(id),
 release_id uuid references public.legal_releases(id),
 acceptance_actor uuid references auth.users(id),
 snapshot jsonb not null,
 recorded_at timestamptz not null default now()
);
alter table public.legal_releases enable row level security;
alter table public.legal_acceptances enable row level security;
alter table public.service_agreements enable row level security;
revoke all on public.legal_releases,public.legal_acceptances,public.service_agreements from public,anon,authenticated;
grant select on public.legal_releases to anon,authenticated;
grant select on public.legal_acceptances,public.service_agreements to authenticated;
grant all on public.legal_releases,public.legal_acceptances,public.service_agreements to service_role;
create policy legal_public_read on public.legal_releases for select to anon,authenticated using(status in ('published','retired'));
create policy legal_admin_draft_read on public.legal_releases for select to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.is_admin and not p.is_suspended));
create policy legal_acceptance_read on public.legal_acceptances for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.is_admin and not p.is_suspended));
create policy service_agreement_read on public.service_agreements for select to authenticated using(client_id=(select auth.uid()) or worker_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.is_admin and not p.is_suspended));

create function private.guard_legal_release() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if old.status in ('published','retired') then
  if tg_op='DELETE' then raise exception 'Una versión publicada debe conservarse';end if;
  if (to_jsonb(new)-'status'-'retired_at') is distinct from (to_jsonb(old)-'status'-'retired_at') or (old.status='retired' and new.status<>'retired') or new.status not in ('published','retired') then raise exception 'Una versión publicada no se puede editar; crea otra versión';end if;
 end if;
 return case when tg_op='DELETE' then old else new end;
end $$;
revoke all on function private.guard_legal_release() from public,anon,authenticated;
create trigger immutable_legal_release before update or delete on public.legal_releases for each row execute function private.guard_legal_release();

create function private.rpc_accept_legal_release(p_release_id uuid,p_audience text,p_terms boolean,p_privacy boolean,p_worker boolean,p_source text) returns public.legal_acceptances language plpgsql security definer set search_path='' as $$
declare r public.legal_releases%rowtype;a public.legal_acceptances%rowtype;u uuid:=auth.uid();
begin
 if u is null or not exists(select 1 from public.profiles where id=u and not is_suspended) then raise exception 'Inicia sesión con una cuenta disponible' using errcode='42501';end if;
 select * into r from public.legal_releases where id=p_release_id and status='published' for share;
 if r.id is null then raise exception 'Esta versión no está vigente. Actualiza los documentos antes de aceptar';end if;
 if p_audience not in ('client','worker') or p_audience is null or p_source not in ('signup','account','checkout') or p_source is null or p_terms is distinct from true or p_privacy is distinct from true or (p_audience='worker' and p_worker is distinct from true) then raise exception 'Confirma las condiciones y la lectura del aviso de privacidad';end if;
 insert into public.legal_acceptances(release_id,user_id,audience,source,terms_accepted,privacy_acknowledged,worker_conditions_accepted,content_sha256)
 values(r.id,u,p_audience,p_source,true,true,p_audience='worker',r.content_sha256)
 on conflict(release_id,user_id,audience) do nothing;
 select * into a from public.legal_acceptances where release_id=r.id and user_id=u and audience=p_audience;
 return a;
end $$;
revoke all on function private.rpc_accept_legal_release(uuid,text,boolean,boolean,boolean,text) from public,anon;
grant execute on function private.rpc_accept_legal_release(uuid,text,boolean,boolean,boolean,text) to authenticated;
create function public.accept_legal_release(p_release_id uuid,p_audience text,p_terms boolean,p_privacy boolean,p_worker boolean,p_source text default 'account') returns public.legal_acceptances language sql security invoker set search_path='' as $$select private.rpc_accept_legal_release(p_release_id,p_audience,p_terms,p_privacy,p_worker,p_source)$$;
revoke all on function public.accept_legal_release(uuid,text,boolean,boolean,boolean,text) from public,anon;
grant execute on function public.accept_legal_release(uuid,text,boolean,boolean,boolean,text) to authenticated;

create function private.rpc_save_legal_draft(p_release_id uuid,p_version text,p_operator jsonb,p_documents jsonb) returns public.legal_releases language plpgsql security definer set search_path='' as $$
declare r public.legal_releases%rowtype;h text;
begin
 if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and is_admin and not is_suspended) then raise exception 'Solo el administrador puede preparar documentos' using errcode='42501';end if;
 if p_version is null or length(trim(p_version)) not between 1 and 60 or jsonb_typeof(p_operator) is distinct from 'object' or jsonb_typeof(p_documents) is distinct from 'array' or jsonb_array_length(p_documents)<>6 or length(p_documents::text)>150000 then raise exception 'Contenido de documentos no válido';end if;
 if (select count(distinct d->>'slug') from jsonb_array_elements(p_documents)d where d->>'slug' in ('terms','worker','privacy','payments','safety','agreement') and length(d->>'title') between 1 and 160 and length(d->>'body') between 50 and 40000)<>6 then raise exception 'Completa los seis documentos sin duplicados';end if;
 h:=encode(sha256(convert_to(jsonb_build_object('version',trim(p_version),'operator',p_operator,'documents',p_documents)::text,'UTF8')),'hex');
 if p_release_id is not null then
  select * into r from public.legal_releases where id=p_release_id for update;
  if r.id is null or r.status<>'draft' then raise exception 'Solo puedes editar un borrador';end if;
  update public.legal_releases set version=trim(p_version),operator=p_operator,documents=p_documents,content_sha256=h where id=r.id returning * into r;
 else
  insert into public.legal_releases(version,operator,documents,content_sha256)values(trim(p_version),p_operator,p_documents,h) returning * into r;
 end if;
 return r;
end $$;
revoke all on function private.rpc_save_legal_draft(uuid,text,jsonb,jsonb) from public,anon;
grant execute on function private.rpc_save_legal_draft(uuid,text,jsonb,jsonb) to authenticated;
create function public.save_legal_draft(p_release_id uuid,p_version text,p_operator jsonb,p_documents jsonb) returns public.legal_releases language sql security invoker set search_path='' as $$select private.rpc_save_legal_draft(p_release_id,p_version,p_operator,p_documents)$$;
revoke all on function public.save_legal_draft(uuid,text,jsonb,jsonb) from public,anon;
grant execute on function public.save_legal_draft(uuid,text,jsonb,jsonb) to authenticated;

create function private.rpc_publish_legal_release(p_release_id uuid) returns public.legal_releases language plpgsql security definer set search_path='' as $$
declare r public.legal_releases%rowtype;k text;txt text;
begin
 if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and is_admin and not is_suspended) then raise exception 'Solo el administrador puede publicar documentos' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtext('dohoy_legal_publish'));
 select * into r from public.legal_releases where id=p_release_id and status='draft' for update;
 if r.id is null then raise exception 'Borrador no disponible';end if;
 foreach k in array array['legal_name','entity_type','address','email','phone'] loop
  if length(trim(coalesce(r.operator->>k,'')))<3 or r.operator->>k ~* '(pendiente|por definir|completar|ejemplo|example|borrador)' then raise exception 'Completa los datos reales del operador: %',k;end if;
 end loop;
 if r.operator->>'entity_type' not in ('Persona física','Persona moral') or r.operator->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or length(regexp_replace(r.operator->>'phone','[^0-9]','','g'))<10 then raise exception 'Revisa el tipo de operador, correo y teléfono';end if;
 txt:=r.documents::text;
 foreach k in array array['legal_name','entity_type','address','email','phone'] loop txt:=replace(txt,'{{'||k||'}}',r.operator->>k);end loop;
 if txt ~ '\{\{[^}]+\}\}' then raise exception 'Quedan datos pendientes en los documentos';end if;
 update public.legal_releases set status='retired',retired_at=now() where status='published';
 update public.legal_releases set status='published',published_at=now() where id=r.id returning * into r;
 return r;
end $$;
revoke all on function private.rpc_publish_legal_release(uuid) from public,anon;
grant execute on function private.rpc_publish_legal_release(uuid) to authenticated;
create function public.publish_legal_release(p_release_id uuid) returns public.legal_releases language sql security invoker set search_path='' as $$select private.rpc_publish_legal_release(p_release_id)$$;
revoke all on function public.publish_legal_release(uuid) from public,anon;
grant execute on function public.publish_legal_release(uuid) to authenticated;

create function private.record_service_agreement() returns trigger language plpgsql security definer set search_path='' as $$
declare t public.tasks%rowtype;o public.task_offers%rowtype;rid uuid;tid uuid;
begin
 if tg_table_name='tasks' then tid:=new.id;else tid:=new.task_id;end if;
 select * into t from public.tasks where id=tid;
 if t.worker_id is null or t.status<>'assigned' then return new;end if;
 select * into o from public.task_offers where task_id=tid and worker_id=t.worker_id and status='accepted' order by created_at desc limit 1;
 if o.id is null then return new;end if;
 select id into rid from public.legal_releases where status='published';
 insert into public.service_agreements(task_id,client_id,worker_id,offer_id,release_id,acceptance_actor,snapshot)
 values(t.id,t.client_id,t.worker_id,o.id,rid,auth.uid(),jsonb_build_object('client_name',(select trim(concat_ws(' ',full_name,last_name)) from public.profiles where id=t.client_id),'worker_name',(select trim(concat_ws(' ',full_name,last_name)) from public.profiles where id=t.worker_id),'title',t.title,'description',t.description,'service_kind',t.service_kind,'recurrence_frequency',t.recurrence_frequency,'scheduled_for',t.scheduled_for,'amount',t.offered_price,'currency','mxn','quote_scope',o.quote_scope,'quote_materials',o.quote_materials,'quote_timeline',o.quote_timeline,'quote_stages',o.quote_stages,'offer_created_at',o.created_at,'counter_accepted',o.counter_status='accepted'))
 on conflict(task_id)do nothing;
 return new;
end $$;
revoke all on function private.record_service_agreement() from public,anon,authenticated;
create trigger record_service_agreement_task after update of worker_id,status on public.tasks for each row execute function private.record_service_agreement();
create trigger record_service_agreement_offer after update of status,counter_status on public.task_offers for each row execute function private.record_service_agreement();

insert into public.legal_releases(version,documents,content_sha256) values('2026-10-19.1','[{"slug": "terms", "title": "Términos para clientes", "summary": "Cuenta, contratación, precio y alcance de DOHOY.", "body": "## 1. Operador y contacto\nDOHOY es operada por {{legal_name}}, {{entity_type}}, con domicilio en {{address}}. Contacto de atención y privacidad: {{email}}. Teléfono de atención: {{phone}}. Estos datos identifican a quien ofrece la plataforma.\n\n## 2. Uso de la cuenta\nLa cuenta es personal. Proporciona información veraz, protege tus credenciales y comunica cualquier uso no autorizado. El uso de los servicios de contratación se dirige a personas mayores de 18 años con capacidad para contratar. No publiques datos de terceros sin autorización ni documentos o información médica innecesarios.\n\n## 3. Cómo se contrata\nDOHOY permite publicar necesidades, recibir propuestas, comparar perfiles y coordinar servicios. En tareas diarias se ofrece un precio; en proyectos se comparan cotizaciones; en recurrentes cada visita es una contratación y pago separados. Una propuesta no asigna por sí sola el servicio: debe existir una aceptación registrada. El alcance y precio aceptados, los materiales, las condiciones y el horario deben consultarse antes del pago.\n\n## 4. Precio, compras y cambios\nEl mínimo de publicación para nuevas tareas diarias es $100 MXN por el servicio. Las compras, materiales y otros gastos no se consideran incluidos salvo que el acuerdo los incorpore expresamente. No autorices cargos o trabajos adicionales sin un acuerdo previo y comprobable. El presupuesto inicial de un proyecto puede ser estimado; el precio acordado es el de la cotización o contraoferta aceptada.\n\n## 5. Pago y finalización\nLos pagos habilitados se procesan mediante Stripe. La pantalla de pago debe mostrar el total y el desglose aplicable antes de confirmar. El trabajo no debe comenzar sin un pago confirmado. El trabajador comunica que terminó y el cliente revisa el resultado y la evidencia antes de confirmar. La confirmación habilita la solicitud de transferencia de ganancias; no acredita por sí sola un depósito bancario inmediato.\n\n## 6. Incumplimientos y derechos\nReporta problemas desde Soporte y disputas, indicando la tarea y la evidencia pertinente. Las reglas de pagos, cancelaciones y seguridad complementan estos términos. Los derechos legales del consumidor y las obligaciones que correspondan a DOHOY o al prestador se mantienen; estos términos no establecen una exención general de responsabilidad ni una renuncia a reclamar ante las autoridades mexicanas competentes.\n\n## 7. Cambios y aceptación\nCada versión identifica su fecha y contenido. Los cambios que requieran aceptación se presentarán antes de continuar con las acciones correspondientes. La actualización no autoriza modificar retroactivamente el precio o alcance ya acordados. Puedes consultar la versión aceptada en el Centro legal. La calificación jurídica de cada relación se determina por las leyes y por la operación real del servicio."}, {"slug": "worker", "title": "Condiciones para trabajadores", "summary": "Propuestas, requisitos, ganancias y revisión de decisiones.", "body": "## 1. Participación\nEstas condiciones regulan el uso de las herramientas de DOHOY por quien ofrece servicios. Identifican al operador {{legal_name}}, con domicilio en {{address}}, correo {{email}} y teléfono {{phone}}. Utiliza una cuenta propia y datos veraces. La participación en servicios se dirige a mayores de 18 años.\n\n## 2. Requisitos y servicios profesionales\nOfrece únicamente actividades para las que tengas capacidad, herramientas y autorizaciones necesarias. Las actividades de conducción requieren licencia y autorizaciones vigentes, además de cobertura y condiciones de uso del vehículo que correspondan. Las profesiones reguladas requieren los títulos, cédulas y permisos aplicables. Una cédula declarada o una calificación de usuarios no equivalen a una verificación oficial, garantía del resultado o seguro.\n\n## 3. Propuestas y ejecución\nRevisa alcance, ubicación, horario y precio antes de enviar o aceptar una propuesta. En proyectos y recurrentes describe qué incluye el servicio, materiales y duración. No cambies unilateralmente lo acordado, no sustituyas a la persona prestadora sin autorización y documenta los cambios solicitados. Comunica retrasos, imposibilidad de asistir o incidentes por los canales disponibles.\n\n## 4. Cuenta de ganancias y pagos\nPara recibir ganancias debes completar el registro de la cuenta de Stripe correspondiente y los requisitos que solicite el procesador. La configuración comercial propuesta de DOHOY es una comisión del 15% y un 85% asignado al prestador, sujetos a los impuestos, retenciones y conceptos legalmente aplicables que deberán mostrarse antes de aceptar. No se promete que el 85% sea un ingreso libre de impuestos. El estado transferido en Stripe y el depósito en el banco son eventos distintos.\n\n## 5. Cierre y desacuerdos\nEl cliente revisa la solicitud de finalización. No solicites confirmar un trabajo pendiente o que no se haya prestado. Si existe desacuerdo, conserva la evidencia y utiliza Soporte y disputas. Un reporte o la revisión de un pago no autoriza una retención indefinida ni la renuncia a derechos o plazos establecidos por ley.\n\n## 6. Calificaciones y decisiones\nDOHOY muestra calificaciones, experiencia, disponibilidad, filtros y señales de compatibilidad como orientación. No garantizan asignación o calidad. Puedes reportar una calificación, una suspensión o una decisión que consideres incorrecta y solicitar revisión humana mediante soporte. Las reglas específicas de gestión algorítmica y de una eventual relación laboral deberán documentarse en el instrumento que legalmente corresponda.\n\n## 7. Régimen aplicable\nEstas condiciones de uso no sustituyen un contrato de trabajo, su registro, obligaciones de seguridad social u otros instrumentos cuando resulten exigibles. No califican automáticamente a todas las personas como independientes. La determinación del régimen laboral, fiscal y de protección aplicable debe atender a la legislación mexicana y a la forma real en que se organiza el servicio. No se renuncia a derechos irrenunciables."}, {"slug": "privacy", "title": "Aviso de privacidad", "summary": "Responsable, datos, finalidades, proveedores y derechos ARCO.", "body": "## 1. Responsable\n{{legal_name}}, con domicilio en {{address}}, es responsable del tratamiento de los datos utilizados por DOHOY. Correo para privacidad y derechos ARCO: {{email}}. Teléfono: {{phone}}.\n\n## 2. Datos tratados\nSegún las funciones que utilices, se tratan nombre, correo, teléfono, perfil, fotografía, información profesional y de verificación, publicaciones, propuestas, mensajes, calificaciones, evidencias, solicitudes de soporte, actividad de uso y registros de errores. La ubicación puede incluir coordenadas del dispositivo y del servicio cuando autorices la función. Stripe procesa los datos necesarios para sus pagos, identificación y cuentas de ganancias mediante sus propios formularios. DOHOY conserva identificadores y estados de esos movimientos; no debe solicitar números completos de tarjeta por chat.\n\n## 3. Finalidades necesarias\nCrear y administrar la cuenta; mostrar y coordinar oportunidades y servicios; intercambiar mensajes; procesar y conciliar pagos; mostrar estados y ganancias; gestionar verificaciones, incidencias y reclamaciones; prevenir usos indebidos; proteger la seguridad; mantener y corregir el producto; atender derechos de las personas y cumplir obligaciones legales. La información que se comparte con la contraparte debe limitarse a lo necesario para el servicio. No se utiliza este aviso para autorizar publicidad opcional ni la venta de datos.\n\n## 4. Ubicación, imágenes y datos sensibles\nLas oportunidades abiertas muestran una ubicación aproximada. Los detalles privados del servicio se reservan para quienes deban conocerlos al contratar. El seguimiento en vivo requiere que la tarea lo solicite y que el trabajador active su GPS; puede detenerlo y no se ofrece una grabación del recorrido. Evita publicar documentos, diagnósticos, datos de salud u otros datos sensibles innecesarios. Si una función llegara a requerir datos sensibles, se deberá informar su finalidad y obtener el consentimiento y protección que correspondan, de manera separada cuando sea exigible.\n\n## 5. Proveedores y comunicaciones\nSupabase proporciona servicios de cuenta, base de datos y almacenamiento; Stripe presta procesamiento de pagos y registro de cuentas de ganancias. Las funciones de mapas, notificaciones y geocodificación pueden comunicar datos técnicos o coordenadas a los proveedores usados por la función. El aviso debe mantenerse consistente con esos proveedores y sus ubicaciones de tratamiento. Los datos pueden comunicarse a participantes del servicio, proveedores que actúan bajo las instrucciones aplicables y autoridades en los supuestos legales; las transferencias que requieran consentimiento deben informarse y recabarse según corresponda.\n\n## 6. Conservación y solicitudes de eliminación\nLos datos se conservarán durante la operación de la cuenta y por los periodos necesarios para las finalidades informadas, obligaciones legales y atención de controversias. Se deberán establecer y aplicar criterios de bloqueo, eliminación y acceso limitado; este aviso no promete eliminación instantánea de registros que deban conservarse. Puedes solicitar eliminación o cierre desde las opciones de cuenta o mediante el contacto de privacidad. Un borrador de soporte y el contacto de confianza pueden guardarse en el propio dispositivo.\n\n## 7. Derechos ARCO y revocación\nPuedes solicitar acceso, rectificación, cancelación u oposición y, cuando proceda, revocar el consentimiento o limitar el uso de datos, escribiendo a {{email}}. Describe el derecho y los datos relacionados y proporciona un medio de respuesta; se solicitará únicamente la acreditación de identidad necesaria. La determinación de una solicitud ARCO se comunicará en un máximo de 20 días hábiles desde su recepción y, cuando proceda, se hará efectiva dentro de los 15 días hábiles siguientes, con las ampliaciones legalmente permitidas y su justificación.\n\n## 8. Seguridad y cambios\nSe deben mantener controles administrativos, técnicos y físicos, limitar el acceso y atender incidentes conforme a la ley. Los cambios se comunicarán mediante el Centro legal y, cuando corresponda, por avisos en la cuenta o los medios registrados. Cada versión podrá consultarse por su fecha. Leer este aviso no equivale a consentir finalidades opcionales no informadas."}, {"slug": "payments", "title": "Pagos, cancelaciones y reembolsos", "summary": "Qué ocurre con el dinero cuando cambia o falla un servicio.", "body": "## 1. Antes de pagar\nRevisa el total en MXN, la propuesta aceptada, materiales incluidos y conceptos aplicables. Las nuevas tareas diarias parten de $100 MXN por el servicio. Las compras y gastos ajenos no están incluidos salvo acuerdo expreso. Los pagos con tarjeta deben cumplir los mínimos del procesador. La propuesta comercial base es 15% de comisión DOHOY y 85% para el prestador, con desglose de impuestos, retenciones y otros conceptos cuando correspondan. El tratamiento fiscal y su implementación deben quedar definidos antes de publicar esta versión como definitiva.\n\n## 2. Cobro y ganancias\nStripe procesa el pago. Un regreso desde su página o un cargo pendiente en el banco no sustituyen la confirmación del procesador. Si hubo una interrupción, utiliza continuar pago para recuperar el intento y consulta su estado antes de volver a pagar. El inicio del trabajo requiere pago confirmado. Al terminar, el cliente revisa y confirma; después se solicita la transferencia que proceda. El depósito bancario depende del estado de la cuenta, las reglas de Stripe y del banco, sin promesa de abono inmediato.\n\n## 3. Cancelación sin pago\nUna publicación sin asignación puede cancelarse desde la tarea. Si ya hay una persona asignada pero el pago no se ha confirmado, comunica la cancelación y revisa si el banco muestra alguna operación pendiente. No se establece en este documento una tarifa automática por cancelación. No puede inventarse un cargo que no se haya informado y aceptado y que no sea legalmente procedente.\n\n## 4. Cancelación después del pago o durante el servicio\nRegistra el motivo y abre un caso de soporte. Cancelar el estado de la tarea no ejecuta por sí mismo un reembolso automático. Se revisarán el pago confirmado, el servicio efectivamente prestado, el acuerdo, materiales autorizados, evidencia y la legislación aplicable para determinar devolución total, parcial u otra solución. Debe comunicarse la resolución y su fundamento; los derechos del consumidor y de la persona prestadora permanecen vigentes.\n\n## 5. Ausencias, resultado y seguridad\nSi una persona no se presenta, el trabajo queda incompleto, se aparta del alcance o hay un incidente, reporta el hecho desde la tarea. Antes de confirmar una finalización que no corresponda, utiliza reportar problema y conserva evidencia. Si confirmaste por error o adviertes un problema después, solicita soporte igualmente; la confirmación no elimina por sí sola los derechos legales.\n\n## 6. Reembolsos y disputas bancarias\nLa devolución debe identificar el pago, monto, motivo, estado y fecha de trámite. La aplicación distingue reembolso total y parcial. La fecha de reflejo depende del procesador y del banco y debe informarse según el caso. Las disputas bancarias pueden requerir evidencia y suspender o revertir movimientos conforme a las reglas aplicables. Stripe no sustituye el procedimiento de atención de DOHOY ni garantiza una resolución favorable a una parte.\n\n## 7. Atención\nUtiliza Soporte y disputas e identifica la tarea. Contacto del operador: {{email}}, {{phone}}. No envíes números completos de tarjeta, contraseñas ni códigos de autenticación. No hay aquí una renuncia a acudir ante las autoridades mexicanas competentes."}, {"slug": "safety", "title": "Seguridad y uso permitido", "summary": "Conducta, servicios restringidos e incidentes.", "body": "## 1. Conducta y cuentas\nNo se permiten fraude, suplantación, documentos falsos, amenazas, discriminación, acoso, violencia, hostigamiento o difusión de datos de otra persona sin justificación. No compartas tu cuenta ni aceptes trabajos a nombre de otra persona sin la autorización y controles que correspondan. Reporta el incidente desde la tarea o soporte.\n\n## 2. Actividades no permitidas\nNo publiques ni aceptes actividades ilícitas, explotación de personas, servicios sexuales, transporte de bienes ilícitos, adquisición de armas o sustancias prohibidas, ni trabajos que busquen evadir requisitos legales. No utilices el servicio para emergencias médicas o situaciones que requieran atención inmediata. El uso para prestar servicios se dirige a mayores de 18 años.\n\n## 3. Actividades con requisitos específicos\nConducir vehículos, intervenir instalaciones de riesgo, realizar obra o prestar servicios médicos, de enfermería, legales u otras profesiones reguladas requiere revisar credenciales, permisos, medidas de seguridad y cobertura aplicables. Hasta contar con los controles adecuados, no debe ofrecerse una actividad como verificada, asegurada o autorizada por DOHOY. Una categoría del catálogo no acredita habilitación profesional.\n\n## 4. Vehículos, inmuebles y pertenencias\nAntes de entregar un automóvil, llaves, herramientas o acceso a un inmueble, acuerden uso autorizado, condiciones y entrega. Documenten el estado cuando sea pertinente y eviten fotografiar datos de terceros. No se ofrece por este texto una póliza de seguro ni cobertura automática por daños; las coberturas y responsabilidades deben verificarse en cada actividad sin excluir las obligaciones legales de las partes.\n\n## 5. Incidentes y revisión\nAnte peligro inmediato, prioriza tu seguridad y la atención de las autoridades o servicios de emergencia. Soporte de DOHOY no es un servicio de respuesta de emergencias. Para revisar un incidente, registra hechos y evidencia pertinente, sin exponer información sensible innecesaria. Las medidas sobre cuentas deben permitir notificación, respuesta y revisión conforme al régimen aplicable.\n\n## 6. Privacidad y contacto\nEl GPS solo debe compartirse mediante las funciones y permisos indicados. No uses datos del servicio para perseguir, divulgar o contactar a otra persona para fines ajenos a lo acordado. Puedes bloquear o reportar conductas y contactar al operador en {{email}} o {{phone}}."}, {"slug": "agreement", "title": "Acuerdo de cada servicio", "summary": "Qué queda registrado cuando se acepta una propuesta.", "body": "## 1. Datos del acuerdo\nEl registro de cada servicio debe identificar la tarea, cliente y prestador, modalidad, descripción, propuesta aceptada y, cuando corresponda, cotización o contraoferta, precio en MXN, alcance, materiales, tiempo estimado, etapas y fecha de aceptación. Las condiciones generales aplicables se identificarán por su versión cuando exista una versión publicada.\n\n## 2. Aceptación y cambios\nEl prestador formula una propuesta y la contraparte la acepta o presenta una contraoferta. La aceptación registrada debe conservar los datos acordados. Los cambios posteriores de precio o alcance requieren un acuerdo verificable; no se consideran autorizados por una edición unilateral o por una nueva versión general de documentos.\n\n## 3. Modalidades\nEn tareas diarias se registra el servicio concreto y su precio. En proyectos se conserva el alcance cotizado y lo incluido en materiales y etapas; la descripción de etapas no significa que la plataforma procese pagos por hitos si esa función no está habilitada. En recurrentes, cada visita se agenda, acepta y paga por separado; la frecuencia no autoriza una suscripción ni cargos automáticos.\n\n## 4. Cumplimiento y evidencia\nEl pago confirmado habilita el inicio conforme a la operación de la tarea. El prestador avisa que terminó y el cliente revisa lo convenido y la evidencia antes de confirmar. Los desacuerdos se atienden mediante soporte y los medios legales que correspondan. El registro no constituye una garantía absoluta del resultado ni una póliza de seguro.\n\n## 5. Alcance jurídico\nEste registro documenta la coordinación y aceptación de un servicio. No reemplaza contratos de obra, de servicios profesionales, de trabajo, consentimientos médicos u otros instrumentos específicos que legalmente resulten exigibles. El operador es {{legal_name}} y puede contactarse en {{email}} o {{phone}}."}]'::jsonb,encode(sha256(convert_to(jsonb_build_object('version','2026-10-19.1','operator','{}'::jsonb,'documents','[{"slug": "terms", "title": "Términos para clientes", "summary": "Cuenta, contratación, precio y alcance de DOHOY.", "body": "## 1. Operador y contacto\nDOHOY es operada por {{legal_name}}, {{entity_type}}, con domicilio en {{address}}. Contacto de atención y privacidad: {{email}}. Teléfono de atención: {{phone}}. Estos datos identifican a quien ofrece la plataforma.\n\n## 2. Uso de la cuenta\nLa cuenta es personal. Proporciona información veraz, protege tus credenciales y comunica cualquier uso no autorizado. El uso de los servicios de contratación se dirige a personas mayores de 18 años con capacidad para contratar. No publiques datos de terceros sin autorización ni documentos o información médica innecesarios.\n\n## 3. Cómo se contrata\nDOHOY permite publicar necesidades, recibir propuestas, comparar perfiles y coordinar servicios. En tareas diarias se ofrece un precio; en proyectos se comparan cotizaciones; en recurrentes cada visita es una contratación y pago separados. Una propuesta no asigna por sí sola el servicio: debe existir una aceptación registrada. El alcance y precio aceptados, los materiales, las condiciones y el horario deben consultarse antes del pago.\n\n## 4. Precio, compras y cambios\nEl mínimo de publicación para nuevas tareas diarias es $100 MXN por el servicio. Las compras, materiales y otros gastos no se consideran incluidos salvo que el acuerdo los incorpore expresamente. No autorices cargos o trabajos adicionales sin un acuerdo previo y comprobable. El presupuesto inicial de un proyecto puede ser estimado; el precio acordado es el de la cotización o contraoferta aceptada.\n\n## 5. Pago y finalización\nLos pagos habilitados se procesan mediante Stripe. La pantalla de pago debe mostrar el total y el desglose aplicable antes de confirmar. El trabajo no debe comenzar sin un pago confirmado. El trabajador comunica que terminó y el cliente revisa el resultado y la evidencia antes de confirmar. La confirmación habilita la solicitud de transferencia de ganancias; no acredita por sí sola un depósito bancario inmediato.\n\n## 6. Incumplimientos y derechos\nReporta problemas desde Soporte y disputas, indicando la tarea y la evidencia pertinente. Las reglas de pagos, cancelaciones y seguridad complementan estos términos. Los derechos legales del consumidor y las obligaciones que correspondan a DOHOY o al prestador se mantienen; estos términos no establecen una exención general de responsabilidad ni una renuncia a reclamar ante las autoridades mexicanas competentes.\n\n## 7. Cambios y aceptación\nCada versión identifica su fecha y contenido. Los cambios que requieran aceptación se presentarán antes de continuar con las acciones correspondientes. La actualización no autoriza modificar retroactivamente el precio o alcance ya acordados. Puedes consultar la versión aceptada en el Centro legal. La calificación jurídica de cada relación se determina por las leyes y por la operación real del servicio."}, {"slug": "worker", "title": "Condiciones para trabajadores", "summary": "Propuestas, requisitos, ganancias y revisión de decisiones.", "body": "## 1. Participación\nEstas condiciones regulan el uso de las herramientas de DOHOY por quien ofrece servicios. Identifican al operador {{legal_name}}, con domicilio en {{address}}, correo {{email}} y teléfono {{phone}}. Utiliza una cuenta propia y datos veraces. La participación en servicios se dirige a mayores de 18 años.\n\n## 2. Requisitos y servicios profesionales\nOfrece únicamente actividades para las que tengas capacidad, herramientas y autorizaciones necesarias. Las actividades de conducción requieren licencia y autorizaciones vigentes, además de cobertura y condiciones de uso del vehículo que correspondan. Las profesiones reguladas requieren los títulos, cédulas y permisos aplicables. Una cédula declarada o una calificación de usuarios no equivalen a una verificación oficial, garantía del resultado o seguro.\n\n## 3. Propuestas y ejecución\nRevisa alcance, ubicación, horario y precio antes de enviar o aceptar una propuesta. En proyectos y recurrentes describe qué incluye el servicio, materiales y duración. No cambies unilateralmente lo acordado, no sustituyas a la persona prestadora sin autorización y documenta los cambios solicitados. Comunica retrasos, imposibilidad de asistir o incidentes por los canales disponibles.\n\n## 4. Cuenta de ganancias y pagos\nPara recibir ganancias debes completar el registro de la cuenta de Stripe correspondiente y los requisitos que solicite el procesador. La configuración comercial propuesta de DOHOY es una comisión del 15% y un 85% asignado al prestador, sujetos a los impuestos, retenciones y conceptos legalmente aplicables que deberán mostrarse antes de aceptar. No se promete que el 85% sea un ingreso libre de impuestos. El estado transferido en Stripe y el depósito en el banco son eventos distintos.\n\n## 5. Cierre y desacuerdos\nEl cliente revisa la solicitud de finalización. No solicites confirmar un trabajo pendiente o que no se haya prestado. Si existe desacuerdo, conserva la evidencia y utiliza Soporte y disputas. Un reporte o la revisión de un pago no autoriza una retención indefinida ni la renuncia a derechos o plazos establecidos por ley.\n\n## 6. Calificaciones y decisiones\nDOHOY muestra calificaciones, experiencia, disponibilidad, filtros y señales de compatibilidad como orientación. No garantizan asignación o calidad. Puedes reportar una calificación, una suspensión o una decisión que consideres incorrecta y solicitar revisión humana mediante soporte. Las reglas específicas de gestión algorítmica y de una eventual relación laboral deberán documentarse en el instrumento que legalmente corresponda.\n\n## 7. Régimen aplicable\nEstas condiciones de uso no sustituyen un contrato de trabajo, su registro, obligaciones de seguridad social u otros instrumentos cuando resulten exigibles. No califican automáticamente a todas las personas como independientes. La determinación del régimen laboral, fiscal y de protección aplicable debe atender a la legislación mexicana y a la forma real en que se organiza el servicio. No se renuncia a derechos irrenunciables."}, {"slug": "privacy", "title": "Aviso de privacidad", "summary": "Responsable, datos, finalidades, proveedores y derechos ARCO.", "body": "## 1. Responsable\n{{legal_name}}, con domicilio en {{address}}, es responsable del tratamiento de los datos utilizados por DOHOY. Correo para privacidad y derechos ARCO: {{email}}. Teléfono: {{phone}}.\n\n## 2. Datos tratados\nSegún las funciones que utilices, se tratan nombre, correo, teléfono, perfil, fotografía, información profesional y de verificación, publicaciones, propuestas, mensajes, calificaciones, evidencias, solicitudes de soporte, actividad de uso y registros de errores. La ubicación puede incluir coordenadas del dispositivo y del servicio cuando autorices la función. Stripe procesa los datos necesarios para sus pagos, identificación y cuentas de ganancias mediante sus propios formularios. DOHOY conserva identificadores y estados de esos movimientos; no debe solicitar números completos de tarjeta por chat.\n\n## 3. Finalidades necesarias\nCrear y administrar la cuenta; mostrar y coordinar oportunidades y servicios; intercambiar mensajes; procesar y conciliar pagos; mostrar estados y ganancias; gestionar verificaciones, incidencias y reclamaciones; prevenir usos indebidos; proteger la seguridad; mantener y corregir el producto; atender derechos de las personas y cumplir obligaciones legales. La información que se comparte con la contraparte debe limitarse a lo necesario para el servicio. No se utiliza este aviso para autorizar publicidad opcional ni la venta de datos.\n\n## 4. Ubicación, imágenes y datos sensibles\nLas oportunidades abiertas muestran una ubicación aproximada. Los detalles privados del servicio se reservan para quienes deban conocerlos al contratar. El seguimiento en vivo requiere que la tarea lo solicite y que el trabajador active su GPS; puede detenerlo y no se ofrece una grabación del recorrido. Evita publicar documentos, diagnósticos, datos de salud u otros datos sensibles innecesarios. Si una función llegara a requerir datos sensibles, se deberá informar su finalidad y obtener el consentimiento y protección que correspondan, de manera separada cuando sea exigible.\n\n## 5. Proveedores y comunicaciones\nSupabase proporciona servicios de cuenta, base de datos y almacenamiento; Stripe presta procesamiento de pagos y registro de cuentas de ganancias. Las funciones de mapas, notificaciones y geocodificación pueden comunicar datos técnicos o coordenadas a los proveedores usados por la función. El aviso debe mantenerse consistente con esos proveedores y sus ubicaciones de tratamiento. Los datos pueden comunicarse a participantes del servicio, proveedores que actúan bajo las instrucciones aplicables y autoridades en los supuestos legales; las transferencias que requieran consentimiento deben informarse y recabarse según corresponda.\n\n## 6. Conservación y solicitudes de eliminación\nLos datos se conservarán durante la operación de la cuenta y por los periodos necesarios para las finalidades informadas, obligaciones legales y atención de controversias. Se deberán establecer y aplicar criterios de bloqueo, eliminación y acceso limitado; este aviso no promete eliminación instantánea de registros que deban conservarse. Puedes solicitar eliminación o cierre desde las opciones de cuenta o mediante el contacto de privacidad. Un borrador de soporte y el contacto de confianza pueden guardarse en el propio dispositivo.\n\n## 7. Derechos ARCO y revocación\nPuedes solicitar acceso, rectificación, cancelación u oposición y, cuando proceda, revocar el consentimiento o limitar el uso de datos, escribiendo a {{email}}. Describe el derecho y los datos relacionados y proporciona un medio de respuesta; se solicitará únicamente la acreditación de identidad necesaria. La determinación de una solicitud ARCO se comunicará en un máximo de 20 días hábiles desde su recepción y, cuando proceda, se hará efectiva dentro de los 15 días hábiles siguientes, con las ampliaciones legalmente permitidas y su justificación.\n\n## 8. Seguridad y cambios\nSe deben mantener controles administrativos, técnicos y físicos, limitar el acceso y atender incidentes conforme a la ley. Los cambios se comunicarán mediante el Centro legal y, cuando corresponda, por avisos en la cuenta o los medios registrados. Cada versión podrá consultarse por su fecha. Leer este aviso no equivale a consentir finalidades opcionales no informadas."}, {"slug": "payments", "title": "Pagos, cancelaciones y reembolsos", "summary": "Qué ocurre con el dinero cuando cambia o falla un servicio.", "body": "## 1. Antes de pagar\nRevisa el total en MXN, la propuesta aceptada, materiales incluidos y conceptos aplicables. Las nuevas tareas diarias parten de $100 MXN por el servicio. Las compras y gastos ajenos no están incluidos salvo acuerdo expreso. Los pagos con tarjeta deben cumplir los mínimos del procesador. La propuesta comercial base es 15% de comisión DOHOY y 85% para el prestador, con desglose de impuestos, retenciones y otros conceptos cuando correspondan. El tratamiento fiscal y su implementación deben quedar definidos antes de publicar esta versión como definitiva.\n\n## 2. Cobro y ganancias\nStripe procesa el pago. Un regreso desde su página o un cargo pendiente en el banco no sustituyen la confirmación del procesador. Si hubo una interrupción, utiliza continuar pago para recuperar el intento y consulta su estado antes de volver a pagar. El inicio del trabajo requiere pago confirmado. Al terminar, el cliente revisa y confirma; después se solicita la transferencia que proceda. El depósito bancario depende del estado de la cuenta, las reglas de Stripe y del banco, sin promesa de abono inmediato.\n\n## 3. Cancelación sin pago\nUna publicación sin asignación puede cancelarse desde la tarea. Si ya hay una persona asignada pero el pago no se ha confirmado, comunica la cancelación y revisa si el banco muestra alguna operación pendiente. No se establece en este documento una tarifa automática por cancelación. No puede inventarse un cargo que no se haya informado y aceptado y que no sea legalmente procedente.\n\n## 4. Cancelación después del pago o durante el servicio\nRegistra el motivo y abre un caso de soporte. Cancelar el estado de la tarea no ejecuta por sí mismo un reembolso automático. Se revisarán el pago confirmado, el servicio efectivamente prestado, el acuerdo, materiales autorizados, evidencia y la legislación aplicable para determinar devolución total, parcial u otra solución. Debe comunicarse la resolución y su fundamento; los derechos del consumidor y de la persona prestadora permanecen vigentes.\n\n## 5. Ausencias, resultado y seguridad\nSi una persona no se presenta, el trabajo queda incompleto, se aparta del alcance o hay un incidente, reporta el hecho desde la tarea. Antes de confirmar una finalización que no corresponda, utiliza reportar problema y conserva evidencia. Si confirmaste por error o adviertes un problema después, solicita soporte igualmente; la confirmación no elimina por sí sola los derechos legales.\n\n## 6. Reembolsos y disputas bancarias\nLa devolución debe identificar el pago, monto, motivo, estado y fecha de trámite. La aplicación distingue reembolso total y parcial. La fecha de reflejo depende del procesador y del banco y debe informarse según el caso. Las disputas bancarias pueden requerir evidencia y suspender o revertir movimientos conforme a las reglas aplicables. Stripe no sustituye el procedimiento de atención de DOHOY ni garantiza una resolución favorable a una parte.\n\n## 7. Atención\nUtiliza Soporte y disputas e identifica la tarea. Contacto del operador: {{email}}, {{phone}}. No envíes números completos de tarjeta, contraseñas ni códigos de autenticación. No hay aquí una renuncia a acudir ante las autoridades mexicanas competentes."}, {"slug": "safety", "title": "Seguridad y uso permitido", "summary": "Conducta, servicios restringidos e incidentes.", "body": "## 1. Conducta y cuentas\nNo se permiten fraude, suplantación, documentos falsos, amenazas, discriminación, acoso, violencia, hostigamiento o difusión de datos de otra persona sin justificación. No compartas tu cuenta ni aceptes trabajos a nombre de otra persona sin la autorización y controles que correspondan. Reporta el incidente desde la tarea o soporte.\n\n## 2. Actividades no permitidas\nNo publiques ni aceptes actividades ilícitas, explotación de personas, servicios sexuales, transporte de bienes ilícitos, adquisición de armas o sustancias prohibidas, ni trabajos que busquen evadir requisitos legales. No utilices el servicio para emergencias médicas o situaciones que requieran atención inmediata. El uso para prestar servicios se dirige a mayores de 18 años.\n\n## 3. Actividades con requisitos específicos\nConducir vehículos, intervenir instalaciones de riesgo, realizar obra o prestar servicios médicos, de enfermería, legales u otras profesiones reguladas requiere revisar credenciales, permisos, medidas de seguridad y cobertura aplicables. Hasta contar con los controles adecuados, no debe ofrecerse una actividad como verificada, asegurada o autorizada por DOHOY. Una categoría del catálogo no acredita habilitación profesional.\n\n## 4. Vehículos, inmuebles y pertenencias\nAntes de entregar un automóvil, llaves, herramientas o acceso a un inmueble, acuerden uso autorizado, condiciones y entrega. Documenten el estado cuando sea pertinente y eviten fotografiar datos de terceros. No se ofrece por este texto una póliza de seguro ni cobertura automática por daños; las coberturas y responsabilidades deben verificarse en cada actividad sin excluir las obligaciones legales de las partes.\n\n## 5. Incidentes y revisión\nAnte peligro inmediato, prioriza tu seguridad y la atención de las autoridades o servicios de emergencia. Soporte de DOHOY no es un servicio de respuesta de emergencias. Para revisar un incidente, registra hechos y evidencia pertinente, sin exponer información sensible innecesaria. Las medidas sobre cuentas deben permitir notificación, respuesta y revisión conforme al régimen aplicable.\n\n## 6. Privacidad y contacto\nEl GPS solo debe compartirse mediante las funciones y permisos indicados. No uses datos del servicio para perseguir, divulgar o contactar a otra persona para fines ajenos a lo acordado. Puedes bloquear o reportar conductas y contactar al operador en {{email}} o {{phone}}."}, {"slug": "agreement", "title": "Acuerdo de cada servicio", "summary": "Qué queda registrado cuando se acepta una propuesta.", "body": "## 1. Datos del acuerdo\nEl registro de cada servicio debe identificar la tarea, cliente y prestador, modalidad, descripción, propuesta aceptada y, cuando corresponda, cotización o contraoferta, precio en MXN, alcance, materiales, tiempo estimado, etapas y fecha de aceptación. Las condiciones generales aplicables se identificarán por su versión cuando exista una versión publicada.\n\n## 2. Aceptación y cambios\nEl prestador formula una propuesta y la contraparte la acepta o presenta una contraoferta. La aceptación registrada debe conservar los datos acordados. Los cambios posteriores de precio o alcance requieren un acuerdo verificable; no se consideran autorizados por una edición unilateral o por una nueva versión general de documentos.\n\n## 3. Modalidades\nEn tareas diarias se registra el servicio concreto y su precio. En proyectos se conserva el alcance cotizado y lo incluido en materiales y etapas; la descripción de etapas no significa que la plataforma procese pagos por hitos si esa función no está habilitada. En recurrentes, cada visita se agenda, acepta y paga por separado; la frecuencia no autoriza una suscripción ni cargos automáticos.\n\n## 4. Cumplimiento y evidencia\nEl pago confirmado habilita el inicio conforme a la operación de la tarea. El prestador avisa que terminó y el cliente revisa lo convenido y la evidencia antes de confirmar. Los desacuerdos se atienden mediante soporte y los medios legales que correspondan. El registro no constituye una garantía absoluta del resultado ni una póliza de seguro.\n\n## 5. Alcance jurídico\nEste registro documenta la coordinación y aceptación de un servicio. No reemplaza contratos de obra, de servicios profesionales, de trabajo, consentimientos médicos u otros instrumentos específicos que legalmente resulten exigibles. El operador es {{legal_name}} y puede contactarse en {{email}} o {{phone}}."}]'::jsonb)::text,'UTF8')),'hex'));
